const { requireRootPath } = require('../git/git_commands');

const PLACEHOLDER_PATTERN = /\{\{\s*(rootProjectFolder|card-file|card-title|card-prompt)\s*\}\}/gu;
const CARD_PROMPT_PLACEHOLDER_PATTERN = /\{\{\s*card-prompt\s*\}\}/u;
const TRACKED_FILE_COMMIT_INSTRUCTION = 'Do not stage or commit changes. md2 will commit files captured from provider edit tools.';

function resolvePlaceholders(text, context, project, extraPrompt) {
    return text.replace(PLACEHOLDER_PATTERN, (_match, name) => {
        if (name === 'rootProjectFolder') return requireRootPath(project);
        if (name === 'card-prompt') return extraPrompt;
        if (name === 'card-title') {
            if (!context.title) throw new Error('Cannot resolve card-title placeholder without a card title');

            return context.title;
        }
        if (!context.file) throw new Error('Cannot resolve card-file placeholder without a file context');

        return context.file;
    });
}

function resolveAgentPrompt(action, context, project, extraPrompt) {
    const prompt = resolvePlaceholders(action.prompt, context, project, extraPrompt);
    if (CARD_PROMPT_PLACEHOLDER_PATTERN.test(action.prompt) || extraPrompt.trim().length === 0) return prompt;

    return `${prompt}\n\n${extraPrompt}`;
}

function withTrackedFileCommitInstruction(prompt, trackFileChanges) {
    return trackFileChanges ? `${prompt}\n\n${TRACKED_FILE_COMMIT_INSTRUCTION}` : prompt;
}

function prepareAgentPrompt(action, context, project, extraPrompt = '') {
    const prompt = resolveAgentPrompt(action, context, project, extraPrompt);

    return withTrackedFileCommitInstruction(prompt, action.trackFileChanges);
}

module.exports = { prepareAgentPrompt, resolveAgentPrompt, resolvePlaceholders, withTrackedFileCommitInstruction };

import { createRequire } from 'node:module';
import { describe, expect, it } from 'vitest';

const require = createRequire(import.meta.url);
const { prepareAgentPrompt, resolveAgentPrompt, resolvePlaceholders } = require('./action_text');

const project = { rootPath: 'C:/repo' };

describe('resolvePlaceholders', () => {
    it('resolves project, card file, card title, and card prompt placeholders', () => {
        const context = { file: 'design/card.md', title: 'Placeholder support' };

        expect(resolvePlaceholders('{{rootProjectFolder}} {{card-file}} {{card-title}} {{card-prompt}}', context, project, 'focus'))
            .toBe('C:/repo design/card.md Placeholder support focus');
    });

    it('rejects missing project root', () => {
        expect(() => resolvePlaceholders('{{rootProjectFolder}}', {}, {}, '')).toThrow('Missing local Git project rootPath');
    });

    it('rejects card-file placeholder without file context', () => {
        expect(() => resolvePlaceholders('{{card-file}}', { kind: 'project' }, project, '')).toThrow('Cannot resolve card-file placeholder');
    });

    it('rejects card-title placeholder without card title', () => {
        expect(() => resolvePlaceholders('{{card-title}}', { kind: 'card' }, project, '')).toThrow('Cannot resolve card-title placeholder');
    });

    it('does not resolve removed placeholder names', () => {
        expect(resolvePlaceholders('{{file}} {{prompt}}', { file: 'design/card.md' }, project, 'focus')).toBe('{{file}} {{prompt}}');
    });
});

describe('resolveAgentPrompt', () => {
    it('replaces card-prompt placeholder', () => {
        expect(resolveAgentPrompt({ prompt: 'Review {{card-prompt}}' }, {}, project, 'this')).toBe('Review this');
    });

    it('appends nonblank input when placeholder is absent', () => {
        expect(resolveAgentPrompt({ prompt: 'Review' }, {}, project, 'this')).toBe('Review\n\nthis');
    });

    it('does not append blank input', () => {
        expect(resolveAgentPrompt({ prompt: 'Review' }, {}, project, '  ')).toBe('Review');
    });
});

describe('prepareAgentPrompt', () => {
    it('includes resolved placeholders and tracked-file instruction', () => {
        const action = { prompt: 'Review {{card-file}} in {{rootProjectFolder}}', trackFileChanges: true };

        expect(prepareAgentPrompt(action, { file: 'design/card.md' }, project)).toBe(
            'Review design/card.md in C:/repo\n\nDo not stage or commit changes. md2 will commit files captured from provider edit tools.',
        );
    });

    it('prepares the custom-prompt action as empty', () => {
        expect(prepareAgentPrompt({ prompt: '{{card-prompt}}' }, {}, project)).toBe('');
    });
});

import type { ActionContext } from '../../data/action_context'
import type { ActionDefinition } from '../../data/action_types'
import type { ProjectReference } from '../../data/data_types'

const PLACEHOLDER_PATTERN = /\{\{\s*(rootProjectFolder|card-file|card-title|card-prompt)\s*\}\}/gu
const CARD_PROMPT_PLACEHOLDER_PATTERN = /\{\{\s*card-prompt\s*\}\}/u

export function resolvePlaceholders(text: string, context: ActionContext, project: ProjectReference, extraPrompt: string): string {
    return text.replace(PLACEHOLDER_PATTERN, (_match, name: string) => {
        if (name === 'rootProjectFolder') {
            if (!project.rootPath) throw new Error('Cannot resolve rootProjectFolder without a local project rootPath')

            return project.rootPath
        }

        if (name === 'card-prompt') return extraPrompt

        if (name === 'card-title') {
            if (!context.title) throw new Error('Cannot resolve card-title placeholder without a card title')

            return context.title
        }

        if (!context.file) throw new Error('Cannot resolve card-file placeholder without a file context')

        return context.file
    })
}

export function resolveAgentPrompt(
    action: ActionDefinition,
    context: ActionContext,
    project: ProjectReference,
    extraPrompt: string,
): string {
    if (!action.prompt) throw new Error(`Missing prompt for agent action "${action.label}"`)
    const resolvedText = resolvePlaceholders(action.prompt, context, project, extraPrompt)
    if (CARD_PROMPT_PLACEHOLDER_PATTERN.test(action.prompt)) return resolvedText
    if (extraPrompt.trim().length === 0) return resolvedText

    return `${resolvedText}\n\n${extraPrompt}`
}

export interface ActionPlaceholder {
    description: string
    name: 'card-file' | 'card-prompt' | 'card-title' | 'rootProjectFolder'
}

export const ACTION_PROMPT_PLACEHOLDERS: readonly ActionPlaceholder[] = [
    { description: 'Path to the selected Markdown card file.', name: 'card-file' },
    { description: 'Title of the selected card.', name: 'card-title' },
    { description: 'Additional prompt entered when the card action runs.', name: 'card-prompt' },
    { description: 'Absolute path to the local project root.', name: 'rootProjectFolder' },
]

/** Format an action placeholder for insertion into template text. */
export function formatActionPlaceholder(name: ActionPlaceholder['name']) {
    return `{{${name}}}`
}

const { exec, spawn } = require('node:child_process');
const path = require('node:path');
const { promisify } = require('node:util');

const { requireRootPath } = require('./git_commands');

const execAsync = promisify(exec);
const DIFF_PLACEHOLDER_PATTERN = /\{\{\s*(rootProjectFolder|commit|branch|file)\s*\}\}/g;
const HUNK_HEADER_PATTERN = /^@@ -(\d+)(?:,\d+)? \+(\d+)(?:,\d+)? @@/;
const DIFF_FILE_HEADER = 'diff --git ';
const OLD_PATH_HEADER = '--- ';
const NEW_PATH_HEADER = '+++ ';

/** Resolve an in-root file path, rejecting paths that escape the project root. */
function resolveInsideRoot(rootPath, targetPath) {
    const resolvedRoot = path.resolve(rootPath);
    const resolvedTarget = path.resolve(resolvedRoot, targetPath);

    if (resolvedTarget !== resolvedRoot && !resolvedTarget.startsWith(`${resolvedRoot}${path.sep}`)) {
        throw new Error('Diff file path escapes project root');
    }

    return resolvedTarget;
}

/** Substitute the diff command placeholders, failing fast when a referenced value is missing. */
function resolveDiffCommand(template, values) {
    if (typeof template !== 'string' || template.length === 0) throw new Error('Missing diff command template');

    return template.replace(DIFF_PLACEHOLDER_PATTERN, (_match, name) => {
        const value = values[name];
        if (typeof value !== 'string' || value.length === 0) throw new Error(`Missing diff command value: ${name}`);

        return value;
    });
}

function stripPathPrefix(rawPath) {
    if (rawPath.startsWith('a/') || rawPath.startsWith('b/')) return rawPath.slice(2);

    return rawPath;
}

function startDiffFile(headerLine) {
    const parts = headerLine.slice(DIFF_FILE_HEADER.length).trim().split(' ');
    const rawPath = parts[parts.length - 1];

    return { newLineNumbers: [], newValue: [], oldLineNumbers: [], oldValue: [], path: stripPathPrefix(rawPath) };
}

function finalizeDiffFile(file) {
    return {
        newLineNumbers: file.newLineNumbers,
        newValue: file.newValue.join('\n'),
        oldLineNumbers: file.oldLineNumbers,
        oldValue: file.oldValue.join('\n'),
        path: file.path,
    };
}

/** Parse unified diff text into per-file old/new sides carrying real file line numbers. */
function parseUnifiedDiff(text) {
    if (typeof text !== 'string' || text.trim().length === 0) throw new Error('Diff command produced no output');

    const files = [];
    let current = null;
    let oldLine = 0;
    let newLine = 0;

    for (const line of text.split(/\r?\n/)) {
        if (line.startsWith(DIFF_FILE_HEADER)) {
            if (current) files.push(finalizeDiffFile(current));
            current = startDiffFile(line);
            continue;
        }
        if (!current) continue;

        if (line.startsWith(OLD_PATH_HEADER)) continue;
        if (line.startsWith(NEW_PATH_HEADER)) {
            current.path = stripPathPrefix(line.slice(NEW_PATH_HEADER.length).trim());
            continue;
        }

        const hunk = HUNK_HEADER_PATTERN.exec(line);
        if (hunk) {
            oldLine = Number(hunk[1]);
            newLine = Number(hunk[2]);
            continue;
        }

        if (line.startsWith(' ')) {
            current.oldValue.push(line.slice(1));
            current.oldLineNumbers.push(oldLine++);
            current.newValue.push(line.slice(1));
            current.newLineNumbers.push(newLine++);
        } else if (line.startsWith('-')) {
            current.oldValue.push(line.slice(1));
            current.oldLineNumbers.push(oldLine++);
        } else if (line.startsWith('+')) {
            current.newValue.push(line.slice(1));
            current.newLineNumbers.push(newLine++);
        }
    }

    if (current) files.push(finalizeDiffFile(current));
    if (files.length === 0) throw new Error('Diff command output could not be parsed');

    return files;
}

/** Run the configured diff command for a commit and return normalized diff data. */
async function generateDiff(project, request, runner = execAsync) {
    const rootPath = requireRootPath(project);
    if (!request || typeof request.commit !== 'string' || request.commit.length === 0) throw new Error('Missing diff commit hash');

    const command = resolveDiffCommand(request.template, {
        branch: request.branch,
        commit: request.commit,
        file: request.filePath,
        rootProjectFolder: rootPath,
    });

    let stdout;
    try {
        ({ stdout } = await runner(command, { cwd: rootPath, maxBuffer: 1024 * 1024 * 32 }));
    } catch (error) {
        const detail = error && typeof error.stderr === 'string' && error.stderr.length > 0 ? error.stderr : error?.message;
        throw new Error(`Diff command failed: ${detail ?? 'unknown error'}`);
    }

    return { commit: request.commit, files: parseUnifiedDiff(stdout) };
}

/** Build the validated `code -g` command that opens a diff file at a line inside the project. */
function buildEditorLaunch(rootPath, request) {
    if (!request || typeof request.path !== 'string' || request.path.length === 0) throw new Error('Missing editor file path');
    if (typeof request.line !== 'number' || !Number.isInteger(request.line) || request.line < 1) throw new Error('Invalid editor line number');

    const resolvedTarget = resolveInsideRoot(rootPath, request.path);

    return `code -g "${resolvedTarget}:${request.line}"`;
}

/** Open VS Code at the clicked diff file/line, rejecting paths that escape the project root. */
function openInEditor(project, request, spawnProcess = spawn) {
    const rootPath = requireRootPath(project);
    const command = buildEditorLaunch(rootPath, request);
    const child = spawnProcess(command, { cwd: rootPath, shell: true });

    return new Promise((resolve, reject) => {
        let isSettled = false;
        const settle = (handler, value) => {
            if (isSettled) return;

            isSettled = true;
            handler(value);
        };

        child.on('error', (error) => {
            const message = error instanceof Error ? error.message : 'unknown error';
            settle(reject, new Error(`Editor launch failed: ${message}`));
        });
        child.on('exit', (code) => {
            if (code === 0 || code === null) {
                settle(resolve);
                return;
            }

            settle(reject, new Error(`Editor launch failed with exit code ${code}`));
        });
    });
}

module.exports = {
    buildEditorLaunch,
    generateDiff,
    openInEditor,
    parseUnifiedDiff,
    resolveDiffCommand,
};

